 const system=document.getElementById('vf-curtain-system');
 const panel=document.getElementById('vf-curtain');
 const label=document.getElementById('vf-curtain-word');
 const top=panel?.querySelector('.vf-curtain-cap.top');
 const bottom=panel?.querySelector('.vf-curtain-cap.bottom');
 if(!system||!panel||!label||!top||!bottom)return;
 const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const normalize=path=>{let p=path.replace(/\/index\.html$/i,'/');if(!p.endsWith('/'))p+='/';return p};
 let active=normalize(location.pathname),busy=false,queued=null;
 const animated=[panel,top,bottom,label];
 const cancel=()=>animated.forEach(e=>e.getAnimations().forEach(a=>a.cancel()));
 const frame=()=>new Promise(resolve=>requestAnimationFrame(resolve));
 const reset=()=>{
   cancel();system.classList.remove('is-active');
   document.documentElement.classList.remove('vf-charges-leaving','vf-charges-incoming');
   panel.style.transform='translate3d(0,118%,0)';
   top.style.transform='scaleY(.12)';bottom.style.transform='scaleY(.12)';
   label.style.opacity='0';label.style.transform='translate3d(0,48px,0)';
 };

 const weddingPackages={
   essential:{name:'Essential',price:'1,400,000'},
   signature:{name:'Signature',price:'2,000,000'},
   premier:{name:'Premier',price:'2,800,000'},
   legacy:{name:'Legacy',price:'3,900,000'}
 };
 function weddingMessage(code){
   const tier=weddingPackages[code];
   return tier?'Hello VIEWFINITY, I have selected the '+tier.name+' wedding package (TZS '+tier.price+'). Let\'s talk further.':'Hello VIEWFINITY, I would like to discuss a wedding package. Let\'s talk further.';
 }
 function syncWeddingSelection(){
   const form=document.getElementById('vf-wedding-booking-form');
   if(!form)return;
   const code=new URLSearchParams(location.search).get('package')||'';
   const select=form.querySelector('#vf-wedding-package');
   select.value=Object.prototype.hasOwnProperty.call(weddingPackages,code)?code:'';
   const message=form.querySelector('#vf-wedding-message');
   if(!form.dataset.userEditedMessage)message.value=weddingMessage(select.value);
 }
 function initWeddingBooking(){
   const form=document.getElementById('vf-wedding-booking-form');
   if(!form)return;
   if(form.dataset.bookingInitialized==='yes'){syncWeddingSelection();return}
   form.dataset.bookingInitialized='yes';
   const select=form.querySelector('#vf-wedding-package');
   const message=form.querySelector('#vf-wedding-message');
   const phone=form.querySelector('#vf-wedding-whatsapp');
   const date=form.querySelector('#vf-wedding-date');
   const status=form.querySelector('#vf-wedding-status');
   const localToday=new Date();
   date.min=localToday.getFullYear()+'-'+String(localToday.getMonth()+1).padStart(2,'0')+'-'+String(localToday.getDate()).padStart(2,'0');
   let country='255';
   try{
     const regions={TZ:'255',KE:'254',UG:'256',RW:'250',US:'1',CA:'1',GB:'44',ZA:'27',NG:'234',GH:'233'};
     const region=new Intl.Locale(navigator.language).region;
     country=regions[region]||country;
   }catch(_){}
   if(!phone.value)phone.value='+'+country+' ';
   syncWeddingSelection();
   message.addEventListener('input',()=>{form.dataset.userEditedMessage='yes'});
   select.addEventListener('change',()=>{
     if(!form.dataset.userEditedMessage)message.value=weddingMessage(select.value);
     select.removeAttribute('aria-invalid');
   });
   for(const input of form.querySelectorAll('input,select,textarea')){
     input.addEventListener('input',()=>{input.removeAttribute('aria-invalid');status.textContent='';status.classList.remove('is-error')});
   }
   form.addEventListener('submit',event=>{
     event.preventDefault();
     status.textContent='';status.classList.remove('is-error');
     const bad=[...form.querySelectorAll('[required]')].find(field=>!field.checkValidity());
     if(bad){bad.setAttribute('aria-invalid','true');bad.focus();bad.reportValidity();status.classList.add('is-error');status.textContent='Please complete all required fields.';return}
     const whatsapp=phone.value.trim(),digits=whatsapp.replace(/\D/g,'');
     if(!/^\+\d[\d\s().-]*$/.test(whatsapp)||digits.length<8||digits.length>15){
       phone.setAttribute('aria-invalid','true');phone.focus();status.classList.add('is-error');status.textContent='Enter your WhatsApp number with a valid international country code.';return;
     }
     const selected=weddingPackages[select.value];
     if(!selected){select.focus();status.classList.add('is-error');status.textContent='Select a wedding package.';return}
     const d=new FormData(form);
     const subject='VIEWFINITY — Wedding booking enquiry — '+selected.name+' — '+date.value;
     const emailBody='VIEWFINITY WEDDING BOOKING ENQUIRY\n\nName: '+d.get('name')+'\nEmail: '+d.get('email')+'\nWhatsApp: '+whatsapp+'\nPackage: '+selected.name+' (TZS '+selected.price+')\nWedding date: '+date.value+'\n\nMessage:\n'+d.get('message');
     const mail='mailto:nelson@viewfinity.art?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(emailBody);
     status.textContent='Your email app will open with your wedding enquiry. Press Send there to deliver it to nelson@viewfinity.art.';
     window.location.href=mail;
   });
 }


